function MetricLineage({ go }: WorkspaceProps) { return <><PageHeading title="Lineage de métrica" description="Seguí el origen de cada número hasta los eventos que lo producen." action={<Button variant="outline" onClick={() => go("PA-091")}>Volver al editor</Button>} /><Card><SectionHeading title="Close rate · v4" description="El cálculo conserva la versión aplicada en cada informe." /><div className="lineage"><div className="lineage-node"><strong>ReservationCreated</strong><span>source event</span></div><div className="lineage-node"><strong>reservations_closed</strong><span>numerador</span></div><div className="lineage-node"><strong>Close rate</strong><span>formula v2</span></div></div><div className="detail-body"><Alert tone="success" title="Origen declarado">La métrica tiene eventos, dimensiones, exclusiones y versión de fórmula.</Alert></div></Card></>; }

function Connectors({ go }: WorkspaceProps) {
  const [connectors, setConnectors] = useState([["W", "WhatsApp", "Canal disponible para el CRM", "Publicado"], ["E", "Email", "Registro histórico de comunicaciones", "Publicado"], ["M", "Meta", "Entrada de consultas sociales", "En revisión"], ["G", "Google Calendar", "Disponibilidad de visitas", "Deprecado"]]);
  const [open, setOpen] = useState(false);
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const register = () => { if (!name.trim()) return; setConnectors((current) => [[name.trim().slice(0, 1).toUpperCase(), name.trim(), description.trim() || "Conector declarado por la plataforma", "En revisión"], ...current]); setName(""); setDescription(""); setOpen(false); };
  return <><PageHeading title="Catálogo de conectores" description="Conectores declarados por la plataforma para que cada experiencia pueda habilitarlos." action={<Button icon="plus" onClick={() => setOpen(true)}>Registrar conector</Button>} /><Card><div className="connector-grid">{connectors.map(([letter, connectorName, connectorDescription, status]) => <article className="connector-card" key={connectorName}><header><span className="connector-logo">{letter}</span><div><strong>{connectorName}</strong><small>platform connector</small></div></header><p>{connectorDescription}</p><footer><StatusBadge status={status === "Publicado" ? "published" : status === "En revisión" ? "review" : "deprecated"} label={status} /><Button variant="ghost" size="xsmall" onClick={() => go("PA-101")}>Ver detalle <Icon name="arrow" size={12} /></Button></footer></article>)}</div></Card><Modal open={open} title="Registrar conector" onClose={() => setOpen(false)} footer={<><Button variant="ghost" onClick={() => setOpen(false)}>Cancelar</Button><Button onClick={register} disabled={!name.trim()}>Registrar</Button></>}><div className="editor-grid"><Field label="Nombre" value={name} onChange={(event) => setName(event.target.value)} placeholder="Ej. Mercado Pago" /><TextAreaField label="Descripción" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="Qué capacidad expone" rows={3} /></div><Alert tone="info" title="Declaración de plataforma">La conexión de una inmobiliaria se configura en su propia experiencia.</Alert></Modal></>;
}

function ConnectorDetail({ go }: WorkspaceProps) { return <><PageHeading title="WhatsApp" description="Definición del conector disponible para experiencias del producto." action={<Button variant="outline" onClick={() => go("PA-100")}>Volver al catálogo</Button>} /><Card><SectionHeading title="Estado del conector" /><div className="detail-body"><div className="definition-grid"><Definition label="Estado" value={<StatusBadge status="published" />} /><Definition label="Versión" value="v2" /><Definition label="Owner" value="platform-config" /><Definition label="Capability" value="COMMUNICATION_HISTORY" /></div><Alert tone="info" title="El conector no se configura acá">Platform Admin declara disponibilidad. La conexión de cada inmobiliaria se gestiona desde su experiencia correspondiente.</Alert></div></Card></>; }

function FeatureFlags({ go, state, dispatch }: WorkspaceProps) { return <><PageHeading title="Feature flags" description="Controles globales para activar capacidades de forma gradual y auditable." action={<Button variant="outline" icon="history" onClick={() => go("PA-140")}>Ver historial</Button>} /><Card><SectionHeading title="Flags globales" description="El estado cambia para nuevas evaluaciones; no reescribe datos históricos." /><div className="flag-list">{Object.entries(state.featureFlags).map(([key, active]) => <div className="flag-row" key={key}><Icon name="flag" size={17} /><div className="flag-copy"><strong>{key}</strong><span>{active === "UNKNOWN" ? "Estado no disponible" : active ? "Activo en Production" : "Preparado para promoción"} · última modificación hace 2 h</span></div><StatusBadge status={active === "UNKNOWN" ? "warning" : active ? "published" : "draft"} label={active === "UNKNOWN" ? "UNKNOWN" : active ? "Activo" : "Inactivo"} /><button type="button" disabled={active === "UNKNOWN"} className={`switch ${active === true ? "is-on" : ""}`} aria-label={`${active === true ? "Desactivar" : "Activar"} ${key}`} aria-pressed={active === true} onClick={() => dispatch({ type: "flag/toggle", key })} /></div>)}</div><Alert tone="info" title="Cambio auditable">Cada activación o desactivación queda lista para registrarse en el historial de plataforma.</Alert></Card></>; }

function Schemas({ go }: WorkspaceProps) {
  const [query, setQuery] = useState("");
  const [filterOpen, setFilterOpen] = useState(false);
  const [entity, setEntity] = useState("all");
  const rows = [["property.extensions", "Property", "v3", "8"], ["party.compliance", "Party", "v2", "5"], ["closing.metadata", "Transaction", "v1", "3"]].filter(([namespace, rowEntity]) => `${namespace} ${rowEntity}`.toLowerCase().includes(query.toLowerCase()) && (entity === "all" || rowEntity === entity));
  return <><PageHeading title="Extension Schemas" description="Extensiones tipadas por namespace y entidad, con validaciones declaradas." action={<Button icon="plus" onClick={() => go("PA-111")}>Nuevo schema</Button>} /><Card><div className="table-toolbar"><div className="toolbar-left"><label className="search-field"><Icon name="search" size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar schema" /></label><Button variant="outline" size="small" icon="filter" aria-expanded={filterOpen} onClick={() => setFilterOpen((value) => !value)}>Filtros</Button>{filterOpen && <label className="inline-filter"><span>Entidad</span><select value={entity} onChange={(event) => setEntity(event.target.value)}><option value="all">Todas</option><option value="Property">Property</option><option value="Party">Party</option><option value="Transaction">Transaction</option></select></label>}</div><Chip tone="neutral">{rows.length} schemas publicados</Chip></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Namespace</th><th>Entidad</th><th>Versión</th><th>Campos</th><th>Estado</th><th /></tr></thead><tbody>{rows.map(([namespace, rowEntity, version, fields]) => <tr key={namespace} onClick={() => go("PA-111")}><td><strong className="mono">{namespace}</strong></td><td>{rowEntity}</td><td>{version}</td><td>{fields}</td><td><StatusBadge status="published" /></td><td><Button variant="ghost" size="xsmall" icon="chevron" aria-label={`Abrir ${namespace}`} onClick={(event) => { event.stopPropagation(); go("PA-111"); }} /></td></tr>)}</tbody></table></div>{!rows.length && <EmptyState icon="schema" title="No encontramos schemas" description="Probá con otro namespace o entidad." />}</Card></>;
}

function SchemaEditor({ state, roleId, issues, go, onOpenValidation, actions, dispatch }: WorkspaceProps) {
  const artifactId = "schema-property-extensions";
  useEnsureDraft(state, dispatch, artifactId, 3);
  const [fields, setFields] = useState([["surfaceM2", "number", "Opcional"], ["zoningCode", "string", "Opcional"], ["isRural", "boolean", "Requerido"]]);
  const [namespace, setNamespace] = useState("property.extensions");
  const [entityType, setEntityType] = useState("Property");
  const [schemaVersion, setSchemaVersion] = useState("3");
  const [rules, setRules] = useState("surfaceM2 > 0");
  const addField = () => setFields((current) => [...current, [`field_${current.length + 1}`, "string", "Opcional"]]);
  const preview = () => { void Promise.all([actions.saveDraft({ artifactId, field: "namespace", value: namespace }), actions.saveDraft({ artifactId, field: "entityType", value: entityType }), actions.saveDraft({ artifactId, field: "schemaVersion", value: schemaVersion }), actions.saveDraft({ artifactId, field: "validationRules", value: rules }), actions.saveDraft({ artifactId, field: "typedFields", value: fields })]); go("PA-112"); };
  return <><PageHeading title="Editor de schema" description="Definí campos tipados y reglas de validación sin colisionar con el core." action={<Button variant="outline" icon="warning" onClick={onOpenValidation}>Validar schema</Button>} /><VersionHeader state={state} roleId={roleId} artifactId={artifactId} title="property.extensions" version={3} issues={issues} onOpenValidation={onOpenValidation} onPublish={() => go("PA-015")} /><Card><SectionHeading title="ExtensionSchema" description="namespace · entityType · schemaVersion · typedFields · validationRules" /><div className="editor-grid"><Field label="Namespace" value={namespace} onChange={(event) => setNamespace(event.target.value)} /><Field label="Entity type" value={entityType} onChange={(event) => setEntityType(event.target.value)} /><Field label="Schema version" type="number" value={schemaVersion} onChange={(event) => setSchemaVersion(event.target.value)} /><Field label="Validation rules" value={rules} onChange={(event) => setRules(event.target.value)} /></div><div className="schema-fields">{fields.map(([name, type, requirement], index) => <div className="schema-field-row" key={`${name}-${index}`}><strong className="mono">{name}</strong><span>{type}</span><span>{requirement}</span><Button variant="ghost" size="xsmall" icon="more" aria-label={`Más opciones para ${name}`} onClick={() => setFields((current) => current.filter((_, fieldIndex) => fieldIndex !== index))} /></div>)}</div><div className="form-actions"><Button variant="outline" icon="plus" onClick={addField}>Agregar campo</Button><Button onClick={preview}>Previsualizar schema</Button></div></Card></>;
}

function SchemaPreview({ go }: WorkspaceProps) { return <><PageHeading title="Vista previa de schema" description="Contrato JSON resultante antes de versionar la extensión." action={<Button variant="outline" onClick={() => go("PA-111")}>Volver al editor</Button>} /><Card><SectionHeading title="property.extensions v3" /><pre className="schema-preview">{`{\n  "namespace": "property.extensions",\n  "entityType": "Property",\n  "schemaVersion": 3,\n  "typedFields": {\n    "surfaceM2": "number",\n    "zoningCode": "string",\n    "isRural": "boolean"\n  },\n  "validationRules": ["surfaceM2 > 0"]\n}`}</pre><div className="detail-body"><Alert tone="success" title="Sin colisiones con el core">Los nombres de campos no reemplazan propiedades propias de Property.</Alert></div></Card></>; }

function Pilots({ state, go }: WorkspaceProps) { return <><PageHeading title="Pilotos y rollout" description="Probá una capability versionada con un conjunto acotado de inmobiliarias." action={<Button icon="plus" onClick={() => go("PA-123")}>Crear piloto</Button>} /><Card><SectionHeading title="Pilotos activos" description="Cada piloto asocia una capability, versión y cohorte." /><div className="pilot-list">{state.pilots.map((pilot) => <div className="pilot-row" key={pilot.id}><div><strong>{pilot.name}</strong><span>{pilot.capability} · v{pilot.version}</span></div><StatusBadge status={pilot.status === "RUNNING" ? "pilot" : "draft"} label={pilot.status === "RUNNING" ? "En curso" : "Borrador"} /><div className="pilot-progress"><div className="progress-track"><i style={{ width: `${pilot.progress}%` }} /></div><small>{pilot.progress}%</small></div><Button variant="ghost" size="xsmall" onClick={() => go("PA-122")}>Abrir <Icon name="arrow" size={12} /></Button></div>)}</div></Card><Card><SectionHeading title="Cohorte" /><div className="detail-body"><div className="cohort-chips">{state.tenantRefs.map((tenant) => <Chip tone={tenant.capabilityState === "PILOT" ? "brand" : "neutral"} key={tenant.id}>{tenant.name}</Chip>)}</div></div></Card></>; }

function PilotDetail({ state, go, fix }: WorkspaceProps) { const pilot = state.pilots[0]; return <><PageHeading title={pilot?.name ?? "Detalle de piloto"} description="Seguimiento de la capability, cohortes y señales del rollout." action={<Button variant="outline" onClick={() => go("PA-124")}>Ver rollout</Button>} meta={<StatusBadge status="pilot" label="En curso" />} /><Card><SectionHeading title="Resumen del piloto" /><div className="detail-body"><div className="definition-grid"><Definition label="Capability" value={pilot?.capability ?? "RENTAL_ADMINISTRATION"} mono /><Definition label="Versión" value={`v${pilot?.version ?? 3}`} /><Definition label="Tenants" value="3" /><Definition label="Progreso" value={`${pilot?.progress ?? 62} %`} /></div><Alert tone="warning" title="Dependencia a revisar">Una inmobiliaria de la cohorte todavía no tiene todos los requisitos declarados.</Alert><div className="form-actions"><Button variant="outline" onClick={() => fix("J7")}>Resolver dependencia</Button><Button onClick={() => go("PA-124")}>Continuar rollout</Button></div></div></Card></>; }

function PilotCreate({ roleId, go, dispatch }: WorkspaceProps) {
  const [capability, setCapability] = useState("RENTAL_ADMINISTRATION");
  const [version, setVersion] = useState("3");
  const [name, setName] = useState("Administración de alquileres");
  const [duration, setDuration] = useState("14 días");
  const [cohort, setCohort] = useState(["Pepito Propiedades", "Vergara & Asociados", "Inmobiliaria Norte"]);
  const allowed = can(roleId, "MANAGE_PILOTS");
  const toggleTenant = (tenant: string) => setCohort((current) => current.includes(tenant) ? current.filter((item) => item !== tenant) : [...current, tenant]);
  const create = () => { if (!allowed || !name.trim() || !cohort.length) return; dispatch({ type: "pilot/create", pilot: { name: name.trim(), capability, version: Number(version), tenants: cohort } }); go("PA-121"); };
  return <><PageHeading title="Crear piloto" description="Elegí una capability y una cohorte pequeña antes de habilitarla." meta={<Chip tone={allowed ? "success" : "error"} icon={allowed ? "check" : "lock"}>{allowed ? "MANAGE_PILOTS habilitado" : "Requiere MANAGE_PILOTS"}</Chip>} /><Card><SectionHeading title="Configuración del piloto" /><div className="editor-grid"><SelectField label="Capability" value={capability} onChange={(event) => setCapability(event.target.value)}><option value="RENTAL_ADMINISTRATION">RENTAL_ADMINISTRATION v3</option><option value="COMPLIANCE_KYC">COMPLIANCE_KYC v4</option></SelectField><Field label="Versión" type="number" value={version} onChange={(event) => setVersion(event.target.value)} /><Field label="Nombre del piloto" value={name} onChange={(event) => setName(event.target.value)} /><Field label="Duración prevista" value={duration} onChange={(event) => setDuration(event.target.value)} /></div><div className="cohort-picker"><strong>Elegí la cohorte</strong>{["Pepito Propiedades", "Vergara & Asociados", "Inmobiliaria Norte", "Almagro Brokers"].map((tenant) => <label key={tenant}><input type="checkbox" checked={cohort.includes(tenant)} onChange={() => toggleTenant(tenant)} />{tenant}</label>)}</div>{!allowed && <Alert tone="error" title="No podés crear pilotos">Tu rol puede consultar releases, pero necesita MANAGE_PILOTS.</Alert>}<div className="form-actions"><Button variant="ghost" onClick={() => go("PA-121")}>Cancelar</Button><Button onClick={create} disabled={!allowed || !name.trim() || !cohort.length}>Crear piloto</Button></div></Card></>;
}

function Rollout({ state, go, dispatch }: WorkspaceProps) {
  const pilot = state.pilots[0];
  const progress = pilot?.progress ?? 0;
  const advance = () => { if (pilot) dispatch({ type: "pilot/advance", pilotId: pilot.id, progress: Math.min(100, progress + 10) }); };
  return <><PageHeading title="Rollout" description="Promové la capability por etapas y monitoreá sus señales." action={<Button variant="outline" onClick={() => go("PA-122")}>Volver al piloto</Button>} /><Card><SectionHeading title={`${pilot?.name ?? "Administración de alquileres"} · v${pilot?.version ?? 3}`} /><div className="rollout"><div className="rollout-track"><div className="rollout-step is-complete"><span className="rollout-dot">✓</span><strong>Preparar</strong><span>Validado</span></div><div className={`rollout-step ${progress < 100 ? "is-current" : "is-complete"}`}><span className="rollout-dot">{progress >= 100 ? "✓" : "2"}</span><strong>Observar</strong><span>{progress}% completo</span></div><div className={`rollout-step ${progress >= 75 ? "is-current" : ""}`}><span className="rollout-dot">{progress >= 100 ? "✓" : "3"}</span><strong>Ampliar</strong><span>{progress >= 75 ? "Listo para ampliar" : "Requiere decisión"}</span></div><div className={`rollout-step ${progress >= 100 ? "is-complete" : ""}`}><span className="rollout-dot">4</span><strong>Completar</strong><span>{progress >= 100 ? "Completado" : "Pendiente"}</span></div></div></div><div className="detail-body"><Alert tone="info" title="Señales del piloto">No se registraron errores críticos en las últimas 24 horas.</Alert><div className="progress-track"><i style={{ width: `${progress}%` }} /></div><div className="form-actions"><Button onClick={advance} disabled={!pilot || progress >= 100}>{progress >= 100 ? "Rollout completado" : "Avanzar 10 %"}</Button></div></div></Card></>;
}

function Environments({ go }: WorkspaceProps) { return <><PageHeading title="Ambientes" description="Compará y promovÉ versiones entre Development, Staging y Production." action={<Button variant="outline" icon="compare" onClick={() => go("PA-126")}>Comparar</Button>} /><Card><SectionHeading title="Estado por ambiente" /><div className="environment-table"><div className="environment-row environment-head"><span>Artefacto</span><span>Development</span><span>Staging</span><span>Production</span><span /></div>{["Argentina Base Pack", "Residential sale", "SALE_DEFAULT"].map((item, index) => <div className="environment-row" key={item}><strong>{item}</strong><span><StatusBadge status="draft" label={`v${index + 9}`} /></span><span><StatusBadge status={index === 0 ? "review" : "published"} label={`v${index + 8}`} /></span><span><StatusBadge status="published" label={`v${index + 7}`} /></span><Button variant="ghost" size="xsmall" onClick={() => go("PA-127")}>Promover</Button></div>)}</div></Card></>; }

function EnvironmentCompare({ go }: WorkspaceProps) {
  const artifacts = ["Argentina Base Pack v8", "Workflow residential-sale v7", "SALE_DEFAULT v5"];
  const [selected, setSelected] = useState(artifacts);
  const toggle = (item: string) => setSelected((current) => current.includes(item) ? current.filter((value) => value !== item) : [...current, item]);
  return <><PageHeading title="Comparar ambientes" description="Revisá las diferencias de Staging antes de promover a Production." action={<Button icon="arrow" onClick={() => go("PA-127")} disabled={!selected.length}>Promover selección ({selected.length})</Button>} /><Card><SectionHeading title="Staging → Production" description={`${selected.length} artefacto${selected.length === 1 ? "" : "s"} seleccionado${selected.length === 1 ? "" : "s"}.`} /><div className="environment-compare"><div className="environment-column"><header>Staging</header>{artifacts.map((item) => <label className="environment-item" key={item}><span><input type="checkbox" checked={selected.includes(item)} onChange={() => toggle(item)} /> {item}</span><StatusBadge status="review" label="Nuevo" /></label>)}</div><div className="compare-arrow"><Icon name="arrow" size={20} /></div><div className="environment-column"><header>Production</header>{["Argentina Base Pack v7", "Workflow residential-sale v6", "SALE_DEFAULT v4"].map((item) => <div className="environment-item" key={item}><span>{item}</span><StatusBadge status="published" label="Actual" /></div>)}</div></div><div className="detail-body"><Alert tone="warning" title="Revisá dependencias">La promoción mantiene el histórico y solo aplica a configuraciones futuras.</Alert></div></Card></>;
}

function Promotion({ state, roleId, fix }: WorkspaceProps) {
  const [promoted, setPromoted] = useState(false);
  const allowed = can(roleId, "PROMOTE");
  const ready = state.journeyFixes.J9;
  return <><PageHeading title="Promoción" description="Promové un artefacto validado al siguiente ambiente." meta={<Chip tone={allowed ? "success" : "error"} icon={allowed ? "check" : "lock"}>{allowed ? "Tenés permiso PROMOTE" : "Requiere PROMOTE"}</Chip>} /><Card><SectionHeading title="Argentina Base Pack v8" description="Staging → Production" /><div className="promotion-summary"><div className="promotion-env"><span>Origen</span><strong>Staging</strong><StatusBadge status="review" label="Validado" /></div><Icon name="arrow" size={20} /><div className="promotion-env"><span>Destino</span><strong>Production</strong><StatusBadge status={ready ? "published" : "error"} label={ready ? "Listo" : "Dependencia faltante"} /></div></div>{!ready && <Alert tone="error" title="Promoción bloqueada">Production todavía no tiene la capability base requerida por esta versión.</Alert>}{promoted && <Alert tone="success" title="Promoción solicitada">El artefacto quedó en proceso de promoción. El historial conservará el correlation ID del BFF.</Alert>}<div className="form-actions"><Button variant="outline" onClick={() => fix("J9")} disabled={ready}>{ready ? "Dependencia resuelta" : "Resolver dependencia"}</Button><Button onClick={() => setPromoted(true)} disabled={!allowed || !ready || promoted}>{promoted ? "Promoción enviada" : "Confirmar promoción"}</Button></div></Card></>;
}

function DeprecatePage({ roleId, go, actions, impact }: WorkspaceProps) {
  const [confirmation, setConfirmation] = useState("");
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const allowed = can(roleId, "DEPRECATE");
  const submit = async () => { if (!allowed || confirmation !== "DEPRECAR" || !reason.trim()) return; setSubmitting(true); try { await actions.deprecate("pack-argentina", reason.trim()); go("PA-011"); } finally { setSubmitting(false); } };
  return <><PageHeading title="Deprecar versión" description="Dejá de ofrecer una versión para nuevas configuraciones sin eliminar su histórico." meta={<Chip tone={allowed ? "warning" : "error"} icon={allowed ? "warning" : "lock"}>{allowed ? `Afecta ${impact.tenantsAffected} tenants activos` : "Requiere DEPRECATE"}</Chip>} /><Card><SectionHeading title="Argentina Base Pack v8" description="Esta acción no borra la versión ni modifica instancias existentes." /><div className="confirmation-box"><Icon name="warning" size={19} /><div><strong>La versión quedará deprecada</strong><p>Las inmobiliarias que ya la usan conservarán su configuración. Las nuevas configuraciones deberán elegir una versión vigente.</p></div><Field label="Confirmación tipeada" value={confirmation} onChange={(event) => setConfirmation(event.target.value)} placeholder="DEPRECAR" hint="Escribí DEPRECAR para habilitar la acción." /><TextAreaField label="Motivo obligatorio" value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Explicá por qué se depreca esta versión" rows={3} /></div>{!allowed && <Alert tone="error" title="Acción restringida">Tu sesión puede consultar el artefacto, pero no tiene el permiso DEPRECATE.</Alert>}<div className="form-actions"><Button variant="ghost" onClick={() => go("PA-011")}>Cancelar</Button><Button variant="danger" icon="warning" onClick={submit} disabled={!allowed || submitting || confirmation !== "DEPRECAR" || !reason.trim()}>{submitting ? "Deprecando…" : "Deprecar versión"}</Button></div></Card></>;
}

export function ValidationDrawer({ state, open, onClose, go, fix, onOpenIssue }: { state: ReviewState; open: boolean; onClose: () => void; go: (id: string) => void; fix: (journey: NonNullable<ValidationIssue["journey"]>) => void; onOpenIssue?: (issue: ValidationIssue) => void }) {
  const issues = validateReviewState(state);
  const counts = validationCounts(issues);
  const grouped = issues.filter((issue) => issue.severity !== "ok").reduce<Record<string, ValidationIssue[]>>((result, issue) => { const category = issue.category ?? "Estructura"; (result[category] ??= []).push(issue); return result; }, {});
  return <Drawer open={open} title="Panel de validación" eyebrow={`${counts.blockers} bloqueos · ${counts.warnings} avisos`} onClose={onClose} footer={<Button variant="outline" onClick={() => { go("PA-034"); onClose(); }}>Abrir pantalla completa</Button>}><p className="drawer-intro">Los bloqueos explican qué relación o regla debe corregirse antes de publicar.</p><div className="drawer-issues">{Object.entries(grouped).map(([category, categoryIssues]) => <section className="drawer-category" key={category}><h3>{category}</h3>{categoryIssues.map((issue) => <div className="drawer-issue" key={issue.code}><span className={`severity-icon severity-${issue.severity}`}>{issue.severity === "blocker" ? "×" : "!"}</span><div><strong>{issue.title}</strong><p>{issue.message}</p><div className="drawer-issue-actions">{issue.journey && <Button variant="outline" size="xsmall" onClick={() => fix(issue.journey!)}>{issue.fixLabel ?? "Resolver"}</Button>}{issue.journey && <Button variant="ghost" size="xsmall" onClick={() => { onOpenIssue?.(issue); go(issueTarget[issue.code] ?? "PA-002"); onClose(); }}>Abrir en el editor</Button>}</div></div></div>)}</section>)}</div><Alert tone="success" title="Controles consistentes">Las versiones publicadas siguen siendo de solo lectura y UNKNOWN se conserva como estado propio.</Alert></Drawer>;
}

function Tenants({ state, go, dispatch }: WorkspaceProps) {
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const tenants = state.tenantRefs.filter((tenant) => `${tenant.name} ${tenant.location}`.toLowerCase().includes(query.toLowerCase()));
  const pages = Math.max(1, Math.ceil(tenants.length / 5));
  const visible = tenants.slice((page - 1) * 5, page * 5);
  useEffect(() => setPage(1), [query]);
  const exportTenants = () => { const csv = ["id,nombre,ubicacion,capability", ...tenants.map((tenant) => `${tenant.id},${tenant.name},${tenant.location},${tenant.capabilityState}`)].join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "platform-admin-tenants.csv"; anchor.click(); URL.revokeObjectURL(url); };
  return <><PageHeading title="Buscar inmobiliaria" description="Consultá el estado de una inmobiliaria y su configuración efectiva." action={<Button variant="outline" icon="download" onClick={exportTenants} disabled={!tenants.length}>Exportar</Button>} /><Card><div className="table-toolbar"><label className="search-field"><Icon name="search" size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por nombre o ubicación" /></label><Chip tone="neutral">{tenants.length} resultados</Chip></div><div className="data-table-wrap"><table className="data-table"><thead><tr><th>Inmobiliaria</th><th>Ubicación</th><th>Capability de alquileres</th><th>Configuración</th><th /></tr></thead><tbody>{visible.map((tenant) => <tr key={tenant.id} onClick={() => { dispatch({ type: "tenant/select", tenantId: tenant.id }); go("PA-131"); }}><td><div className="table-primary"><span className="connector-logo"><Icon name="tenant" size={15} /></span><div><strong>{tenant.name}</strong><small>{tenant.id}</small></div></div></td><td>{tenant.location}</td><td><StatusBadge status={tenant.capabilityState === "PILOT" ? "pilot" : "published"} label={tenant.capabilityState === "PILOT" ? "Piloto" : "Habilitada"} /></td><td>Argentina Base Pack v8</td><td><Button variant="ghost" size="xsmall" icon="chevron" aria-label={`Abrir ${tenant.name}`} /></td></tr>)}</tbody></table></div>{!tenants.length && <EmptyState icon="tenant" title="No encontramos inmobiliarias" description="Probá con otro nombre o ubicación." />}<Pagination page={page} pages={pages} onChange={setPage} /></Card></>;
}

function TenantDetail({ state, go, dispatch }: WorkspaceProps) {
  const tenant = state.tenantRefs.find((item) => item.id === state.selectedTenantId) ?? state.tenantRefs[0];
  return <><PageHeading title={tenant?.name ?? "Inmobiliaria"} description="Configuración aplicada, capabilities habilitadas y acciones administrativas." meta={<><Chip tone="neutral">{tenant?.location ?? "—"}</Chip><StatusBadge status="published" label="Activa" /></>} action={<Button variant="outline" icon="layers" onClick={() => go("PA-132")}>Ver configuración efectiva</Button>} /><Card><SectionHeading title="Resumen de la inmobiliaria" /><div className="detail-body"><div className="definition-grid"><Definition label="Identificador" value={tenant?.id ?? "UNKNOWN"} mono /><Definition label="Pack efectivo" value="Argentina Base Pack v8" /><Definition label="Estado de capability" value={<StatusBadge status={tenant?.capabilityState === "PILOT" ? "pilot" : "published"} label={tenant?.capabilityState === "PILOT" ? "Piloto" : "Habilitada"} />} /><Definition label="Overrides" value="3 configuraciones" /></div><Alert tone="info" title="Los overrides son de solo lectura acá">Platform Admin explica la precedencia, pero no edita configuración específica de una inmobiliaria.</Alert><div className="form-actions"><Button variant="outline" icon="layers" onClick={() => go("PA-132")}>Inspeccionar precedencia</Button><Button variant="outline" icon="wrench" onClick={() => go("PA-142")}>Ver correcciones</Button><Button variant="ghost" onClick={() => { const next = state.tenantRefs.find((item) => item.id !== tenant?.id); if (next) dispatch({ type: "tenant/select", tenantId: next.id }); }}>Cambiar inmobiliaria</Button></div></div></Card><Card><SectionHeading title="Capacidades activas" /><div className="reference-list">{["PROPERTY_CORE v2", "CLOSING_WORKFLOW v4", "COMMUNICATION_HISTORY v2"].map((item) => <div className="reference-row" key={item}><Icon name="toggle" size={16} /><div><strong>{item}</strong><span>Habilitada por el pack efectivo</span></div><StatusBadge status="published" label="Activa" /></div>)}</div></Card></>;
}

function EffectiveInspector({ state, go, dispatch }: WorkspaceProps) {
  const config = state.effectiveConfiguration;
  const tenant = state.tenantRefs.find((item) => item.id === state.selectedTenantId) ?? state.tenantRefs[0];
  const [tab, setTab] = useState("resolution");
  const [operation, setOperation] = useState("Compraventa");
  const [stage, setStage] = useState("Preparing");
  const rows = [{ label: "Default de plataforma", value: config.defaultValue, source: "Platform default", result: "Base" }, { label: "Default de capability", value: "4 %", source: "PROPERTY_CORE v2", result: "Base" }, { label: "Override de pack", value: "4 %", source: config.pack, result: "Precede al default" }, { label: "Override de inmobiliaria", value: config.tenantOverride, source: tenant?.name ?? "UNKNOWN", result: "Precede al pack" }, { label: "Valor efectivo", value: config.effectiveValue, source: "Resultado aplicado", result: "Gana" }];
  return <><PageHeading title="Configuración efectiva" description="Inspeccioná qué valor gana, de dónde viene y por qué." meta={<Chip tone="info" icon="lock">Solo lectura</Chip>} action={<Button variant="outline" onClick={() => go("PA-131")}>Volver a la inmobiliaria</Button>} /><Card><Tabs tabs={[{ id: "resolution", label: "Resolución" }, { id: "sources", label: "Fuentes" }, { id: "overrides", label: "Overrides" }, { id: "history", label: "Historial" }]} active={tab} onChange={setTab} />{tab === "resolution" && <><div className="inspector-context"><label className="context-box"><span>Inmobiliaria</span><select value={tenant?.id ?? ""} onChange={(event) => dispatch({ type: "tenant/select", tenantId: event.target.value })}>{state.tenantRefs.map((item) => <option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="context-box"><span>Operación</span><select value={operation} onChange={(event) => setOperation(event.target.value)}><option>Compraventa</option><option>Locación</option></select></label><label className="context-box"><span>Etapa</span><select value={stage} onChange={(event) => setStage(event.target.value)}><option>Preparing</option><option>Due diligence</option><option>Ready to close</option></select></label><div className="context-box"><span>Ambiente</span><strong>{state.environment}</strong></div></div><div className="resolution-tree">{rows.map((row, index) => <div className={`resolution-row ${index === rows.length - 1 ? "is-effective" : ""}`} key={row.label}><strong>{row.label}</strong><span>{row.value}</span><span>{row.source}</span><span className={index === rows.length - 1 ? "effective" : ""}>{row.result}</span></div>)}</div><div className="why-box"><strong>Por qué:</strong> {config.why} Contexto: {operation} · {stage}. Las instancias históricas mantienen la configuración con la que fueron creadas.</div></>}{tab === "sources" && <div className="detail-body"><SectionHeading title="Familias de precedencia" description="La resolución consulta cada fuente en un orden estable." /><div className="reference-list">{["Platform default", "Capability default", "Pack override", "Tenant override"].map((source, index) => <div className="reference-row" key={source}><span className="priority-index">{index + 1}</span><div><strong>{source}</strong><span>{index === 3 ? tenant?.name ?? "UNKNOWN" : index === 2 ? config.pack : "Configuración compartida"}</span></div><StatusBadge status="published" label={index === 3 ? "Aplicado" : "Consultado"} /></div>)}</div></div>}{tab === "overrides" && <div className="detail-body"><Alert tone="info" title="override dentro de límites">Este módulo es de solo lectura: muestra el valor que se aplicaría sin permitir editarlo.</Alert><div className="definition-grid"><Definition label="Mínimo publicado" value="2 %" /><Definition label="Máximo publicado" value="6 %" /><Definition label="Override" value={config.tenantOverride} /><Definition label="Efectivo" value={config.effectiveValue} /></div></div>}{tab === "history" && <div className="history-list">{["Override creado para la inmobiliaria", "Pack Argentina Base v8 publicado", "Default de capability actualizado"].map((item, index) => <div className="history-row" key={item}><span className="history-time">{index + 1} sep 2026</span><div><strong>{item}</strong><span>{tenant?.name ?? "UNKNOWN"} · configuración preservada</span></div></div>)}</div>}</Card><Card><Alert tone="info" title="Sin mutación desde este módulo">Para cambiar un override se usa la experiencia de la inmobiliaria y se conserva la auditoría.</Alert></Card></>;
}

function AuditPage({ state, roleId, go, dispatch }: WorkspaceProps) {
  const allowed = can(roleId, "VIEW_AUDIT");
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const filtered = state.audit.filter((entry) => `${entry.action} ${entry.actor} ${entry.correlationId} ${entry.artifact}`.toLowerCase().includes(query.toLowerCase()));
  const pages = Math.max(1, Math.ceil(filtered.length / 8));
  const entries = filtered.slice((page - 1) * 8, page * 8);
  useEffect(() => setPage(1), [query]);
  const download = () => { const csv = ["timestamp,action,artifact,actor,reason,correlationId,before,after", ...filtered.map((entry) => [entry.timestamp, entry.action, entry.artifact, entry.actor, entry.reason, entry.correlationId, formatAuditValue(entry.before), formatAuditValue(entry.after)].map((value) => `"${value.replaceAll('"', '""')}"`).join(","))].join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "platform-admin-audit.csv"; anchor.click(); URL.revokeObjectURL(url); };
  return <><PageHeading title="Registro de auditoría" description="Acciones de configuración, publicación, promoción y corrección con su correlación." meta={<Chip tone={allowed ? "success" : "error"} icon={allowed ? "check" : "lock"}>{allowed ? "Auditoría habilitada" : "Requiere VIEW_AUDIT"}</Chip>} /><Card>{allowed ? <><div className="audit-filters"><label className="search-field"><Icon name="search" size={14} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar acción, actor o correlación" /></label><Chip tone="neutral">{filtered.length} registros</Chip><Button variant="outline" size="small" icon="download" onClick={download} disabled={!filtered.length}>Descargar</Button></div><div className="data-table-wrap"><table className="data-table audit-table"><thead><tr><th>Fecha</th><th>Acción</th><th>Artefacto</th><th>Actor</th><th>Motivo</th><th>Correlation ID</th><th /></tr></thead><tbody>{entries.map((entry) => <tr key={entry.id} onClick={() => { dispatch({ type: "audit/select", auditId: entry.id }); go("PA-141"); }}><td>{entry.timestamp}</td><td><strong>{entry.action}</strong></td><td>{entry.artifact}</td><td>{entry.actor}</td><td>{entry.reason}</td><td className="correlation">{entry.correlationId}</td><td><Button variant="ghost" size="xsmall" icon="chevron" aria-label="Ver detalle de auditoría" /></td></tr>)}</tbody></table></div><Pagination page={page} pages={pages} onChange={setPage} /></> : <NoPermission {...({ screen: getScreenById("PA-140")!, state, roleId, issues: [], dispatch: (() => undefined) as ReviewDispatch, go, fix: (() => undefined) as WorkspaceProps["fix"], onOpenValidation: () => undefined, actions: defaultWorkspaceActions, artifacts: reviewArtifacts, impact: reviewImpact } as WorkspaceProps)} />}</Card></>;
}

function formatAuditValue(value: unknown): string {
  if (typeof value === "string") return value;
  try { return JSON.stringify(value) ?? "UNKNOWN"; } catch { return "UNKNOWN"; }
}

function AuditDetail({ state, roleId, go, dispatch }: WorkspaceProps) {
  const entry = state.audit.find((item) => item.id === state.selectedAuditId) ?? state.audit[0];
  const correlation = formatCorrelationId(entry?.correlationId);
  const copyCorrelationId = async () => { try { if (!navigator.clipboard) throw new Error("clipboard unavailable"); await navigator.clipboard.writeText(correlation.copyValue); dispatch({ type: "toast/show", message: "Correlation ID copiado." }); } catch { dispatch({ type: "toast/show", message: "No se pudo copiar el correlation ID." }); } };
  if (!can(roleId, "VIEW_AUDIT")) return <NoPermission screen={getScreenById("PA-141")!} state={state} roleId={roleId} issues={[]} dispatch={(() => undefined) as ReviewDispatch} go={go} fix={() => undefined} onOpenValidation={() => undefined} actions={defaultWorkspaceActions} artifacts={reviewArtifacts} impact={reviewImpact} />;
  return <><PageHeading title="Detalle de auditoría" description="Evidencia completa de una acción administrativa." action={<Button variant="outline" onClick={() => go("PA-140")}>Volver al registro</Button>} /><Card><div className="detail-body"><div className="definition-grid"><Definition label="Acción" value={entry?.action ?? "Sin acción"} /><Definition label="Artefacto" value={entry?.artifact ?? "UNKNOWN"} /><Definition label="Actor" value={entry?.actor ?? "UNKNOWN"} /><Definition label="Correlation ID" value={<span className="inline-value"><span className="mono">{correlation.displayValue}</span><Button variant="ghost" size="xsmall" icon="copy" aria-label="Copiar correlation ID" onClick={() => void copyCorrelationId()} /></span>} /><Definition label="Fecha" value={entry?.timestamp ?? "UNKNOWN"} /><Definition label="Motivo" value={entry?.reason ?? "UNKNOWN"} /></div><div className="audit-evidence-grid"><div><SectionHeading title="Antes" description="Estado observado antes de la acción." /><pre className="schema-preview">{formatAuditValue(entry?.before)}</pre></div><div><SectionHeading title="Después" description="Estado producido o solicitado por la acción." /><pre className="schema-preview">{formatAuditValue(entry?.after)}</pre></div></div><Alert tone="success" title="Registro inmutable">La entrada no se edita ni se elimina. Las correcciones posteriores crean nuevos eventos.</Alert></div></Card></>;
}

function Corrections({ go }: WorkspaceProps) {
  const commands = [["Reprocesar caso documental", "Reevalúa el estado de un caso con la versión vigente", "ADMIN_CORRECTION"], ["Recalcular configuración efectiva", "Reconstruye el read model de una inmobiliaria", "ADMIN_CORRECTION"], ["Reconciliar referencia de pack", "Corrige una referencia publicada inconsistente", "ADMIN_CORRECTION"]];
  const [selected, setSelected] = useState(0);
  const command = commands[selected];
  return <><PageHeading title="Catálogo de correcciones" description="Comandos excepcionales, autorizados y siempre auditados." meta={<Chip tone="warning" icon="warning">Uso restringido</Chip>} /><Card><div className="correction-grid"><div className="correction-menu">{commands.map(([name], index) => <button className={index === selected ? "is-selected" : ""} type="button" key={name} onClick={() => setSelected(index)}>{name}</button>)}</div><div className="correction-content"><SectionHeading title={command[0]} description={command[1]} /><div className="definition-grid"><Definition label="Permiso" value={<Chip tone="error" icon="lock">{command[2]}</Chip>} /><Definition label="Impacto" value={selected === 0 ? "Un caso seleccionado" : selected === 1 ? "Read model de una inmobiliaria" : "Referencia de pack publicada"} /><Definition label="Auditoría" value="Obligatoria" /><Definition label="Histórico" value="No se elimina" /></div><Alert tone="warning" title="Acción excepcional">El comando no cambia el dominio sin un motivo y queda asociado a un correlation ID.</Alert><Button icon="arrow" onClick={() => go("PA-143")}>Abrir flujo de corrección</Button></div></div></Card></>;
}

function CorrectionFlow({ state, roleId, go, actions }: WorkspaceProps) {
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const allowed = can(roleId, "ADMIN_CORRECTION");
  const submit = async () => { if (!allowed || !reason.trim()) return; setSubmitting(true); try { await actions.executeCorrection({ commandId: "REPROCESS_COMPLIANCE_CASE", targetId: "compliance-case-784", reason: reason.trim() }); go("PA-141"); } finally { setSubmitting(false); } };
  return <><PageHeading title="Flujo de corrección" description="Autorizá una corrección administrativa con alcance, motivo y evidencia." meta={<Chip tone={allowed ? "success" : "error"} icon={allowed ? "check" : "lock"}>{allowed ? "Permiso ADMIN_CORRECTION" : "Requiere ADMIN_CORRECTION"}</Chip>} /><Card><SectionHeading title="Reprocesar caso documental" description="La corrección se ejecuta en el servicio owner y deja auditoría." /><div className="correction-form"><div className="definition-grid"><Definition label="Target" value="compliance-case-784" mono /><Definition label="Comando" value="REPROCESS_COMPLIANCE_CASE" mono /><Definition label="Ambiente" value={state.environment} /><Definition label="Permiso" value="ADMIN_CORRECTION" /></div><TextAreaField label="Motivo obligatorio" value={reason} onChange={(event) => setReason(event.target.value)} placeholder="Explicá por qué esta corrección es necesaria" rows={4} hint="Se guardará en la auditoría junto con el actor y la correlación." />{!allowed && <Alert tone="error" title="No podés ejecutar esta corrección">Tu sesión puede consultar el catálogo, pero necesita el permiso ADMIN_CORRECTION. Contactá a un admin de plataforma o a soporte autorizado.</Alert>}{allowed && <Alert tone="info" title="Confirmación previa">La corrección no elimina datos ni cambia versiones publicadas; solo solicita una acción excepcional al owner.</Alert>}<div className="form-actions"><Button variant="ghost" onClick={() => go("PA-142")}>Cancelar</Button><Button icon="wrench" onClick={submit} disabled={!allowed || submitting || !reason.trim()}>{submitting ? "Autorizando…" : "Autorizar corrección"}</Button></div></div></Card></>;
}

function GlobalSearchPage({ go }: WorkspaceProps) {
  const [query, setQuery] = useState("");
  const results = screenRegistry.filter((screen) => `${screen.title} ${screen.group} ${screen.id}`.toLowerCase().includes(query.toLowerCase())).slice(0, 12);
  return <><PageHeading title="Búsqueda global" description="Encontrá artefactos, pantallas y módulos desde un único lugar." /><Card><div className="global-search-box"><label className="search-field search-field-large"><Icon name="search" size={17} /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar por nombre, módulo o código" /></label><span className="search-hint">También podés abrir esta búsqueda con Ctrl K.</span></div><div className="search-result-list">{results.map((screen) => <button type="button" className="search-result-row" key={screen.id} onClick={() => go(screen.id)}><Icon name={screen.module === "pack" ? "package" : screen.module === "rules" ? "workflow" : "layers"} size={16} /><span><strong>{screen.title}</strong><small>{screen.id} · {screen.group}</small></span><Icon name="chevron" size={14} /></button>)}{!results.length && <EmptyState title="Sin resultados" description="Probá con otra palabra o un código PA." />}</div></Card></>;
}

function ProductHistory({ state, go }: WorkspaceProps) {
  return <><PageHeading title="Historial de cambios de producto" description="Lanzamientos y decisiones que cambiaron la configuración disponible." action={<Button variant="outline" icon="audit" onClick={() => go("PA-140")}>Ver auditoría</Button>} /><Card><div className="history-timeline">{[{ date: "7 sep 2026", title: "Argentina Base Pack v8 publicado", detail: "Nueva composición para compraventa residencial · 12 inmobiliarias", status: "Publicado" }, { date: "5 sep 2026", title: "Residential sale v7 disponible", detail: "Se agregó Due diligence y se preservaron las instancias históricas", status: "Publicado" }, { date: "2 sep 2026", title: "Property types v5 actualizado", detail: "Catálogo base con 18 entradas estables", status: "Publicado" }].map((item) => <div className="history-timeline-row" key={item.title}><span className="timeline-dot" /><div><span className="history-time">{item.date}</span><strong>{item.title}</strong><span>{item.detail}</span></div><StatusBadge status="published" label={item.status} /></div>)}</div><div className="detail-body"><Alert tone="info" title="Histórico preservado">La publicación solo afecta configuraciones futuras; cada instancia conserva la versión aplicada.</Alert><span className="muted">Última sincronización: {state.environment} · hace 2 min</span></div></Card></>;
}

function NoPermission({ roleId, go }: WorkspaceProps) {
  const role = getRole(roleId);
  return <div className="no-permission"><div className="lock-mark"><Icon name="lock" size={24} /></div><h1>Acción restringida</h1><p className="lead-copy">Tu sesión como {role.name} puede consultar esta plataforma, pero no tiene el permiso requerido para ejecutar esta acción.</p><Alert tone="warning" title="Permiso requerido">La acción permanece visible para que entiendas qué falta y quién puede ejecutarla.</Alert><div className="permission-explanation"><strong>Permisos actuales</strong><div className="permission-list">{role.permissions.map((permission) => <Chip tone="info" key={permission}>{permission}</Chip>)}</div><span>Solicitá el permiso al responsable de plataforma.</span></div><Button variant="outline" onClick={() => go("PA-001")}>Volver al inicio</Button></div>;
}

function VersionHeaderPage({ state, roleId, issues, onOpenValidation, go }: WorkspaceProps) {
  return <><PageHeading title="Encabezado de versión" description="Patrón transversal para distinguir borradores, publicaciones, validaciones y acciones disponibles." /><VersionHeader state={state} roleId={roleId} title="Ejemplo de artefacto" version={3} issues={issues} onOpenValidation={onOpenValidation} onNewVersion={() => go("PA-013")} onPublish={() => go("PA-015")} /><Card><SectionHeading title="Reglas del patrón" /><div className="definition-grid"><Definition label="Publicado" value="Solo lectura" /><Definition label="Edición" value="Crea un nuevo borrador" /><Definition label="Guardado" value="No publica" /><Definition label="Bloqueos" value="Detienen publicación" /></div><Alert tone="info" title="Acciones restringidas visibles">Los botones que no podés usar explican el permiso o el bloqueo sin desaparecer.</Alert></Card></>;
}
